import { z } from "zod";

// Jarvis Mode contracts (Zeno for administrators). Each schema mirrors one
// response or request model in broka/backend/api/domains/admin_zeno/schemas.py.
//
// Objects are strict: a key the backend does not define fails validation
// instead of being silently dropped. A backend Optional field is nullable
// here, never defaulted, so a missing value is not mistaken for zero. Shared
// by the server proxy (validates upstream replies) and the browser hooks
// (validates what the proxy returns).

/** Conversation and turn ids are UUID4 strings generated by the backend. */
export const ZENO_CONVERSATION_ID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export const ZENO_BRIEFING_WINDOW = { min: 1, max: 30, default: 7 } as const;
export const ZENO_CHAT_PERIOD = { min: 1, max: 90 } as const;
export const ZENO_LIST_PAGE = { min: 1, max: 50 } as const;
export const ZENO_TURN_PAGE = { min: 1, max: 40 } as const;

const OFFSET_SUFFIX = /(?:Z|[+-]\d{2}:\d{2})$/i;

/**
 * The backend serialises naive UTC datetimes with no offset. Read without a
 * zone, a browser treats them as local time, so an offset of Z is appended and
 * the value is normalised to canonical UTC ISO text.
 */
export function toUtcIso(value: string): string {
  const withZone = OFFSET_SUFFIX.test(value) ? value : `${value}Z`;
  const time = Date.parse(withZone);
  return Number.isFinite(time) ? new Date(time).toISOString() : withZone;
}

export const UtcDateTimeSchema = z
  .string()
  .datetime({ offset: true, local: true })
  .transform(toUtcIso);

/**
 * Backend `Any`: a number, string, boolean, null, or a small structured value.
 * A union rather than z.unknown(), because z.unknown() accepts a missing key
 * and the contract always sends one.
 */
const JsonValueSchema = z.union([
  z.string(),
  z.number(),
  z.boolean(),
  z.null(),
  z.array(z.unknown()),
  z.record(z.string(), z.unknown()),
]);

export const ZenoConfidenceSchema = z.enum(["measured", "derived", "estimated", "hypothesis", "unavailable"]);
export type ZenoConfidence = z.infer<typeof ZenoConfidenceSchema>;

export const ZenoPeriodSchema = z.object({
  start: UtcDateTimeSchema.nullable(),
  end: UtcDateTimeSchema.nullable(),
  timezone: z.string().min(1).max(40),
}).strict();
export type ZenoPeriod = z.infer<typeof ZenoPeriodSchema>;

export const ZenoEvidenceSchema = z.object({
  id: z.string().min(1).max(160),
  metric_key: z.string().min(1).max(200),
  label: z.string().min(1).max(160),
  value: JsonValueSchema,
  unit: z.string().max(40),
  previous_value: JsonValueSchema,
  period: ZenoPeriodSchema,
  source: z.string().min(1).max(120),
  definition: z.string().max(1200),
  generated_at: UtcDateTimeSchema,
  available: z.boolean(),
  unavailable_reason: z.string().max(800).nullable(),
  confidence: ZenoConfidenceSchema,
  href: z.string().max(240).nullable(),
}).strict();
export type ZenoEvidence = z.infer<typeof ZenoEvidenceSchema>;

export const ZenoDerivationSchema = z.enum(["value", "previous_value", "delta", "pct_change"]);

export const ZenoClaimSchema = z.object({
  metric_key: z.string().min(1).max(200),
  asserted_value: JsonValueSchema,
  unit: z.string().max(40),
  evidence_reference: z.string().min(1).max(200),
  derivation: ZenoDerivationSchema,
  confidence: ZenoConfidenceSchema,
}).strict();
export type ZenoClaim = z.infer<typeof ZenoClaimSchema>;

export const ZenoFindingSchema = z.object({
  statement: z.string().max(800),
  evidence: z.array(z.string()).max(12),
  claims: z.array(ZenoClaimSchema).max(8),
  confidence: ZenoConfidenceSchema,
}).strict();
export type ZenoFinding = z.infer<typeof ZenoFindingSchema>;

export const ZenoInterpretationSchema = z.object({
  statement: z.string().max(800),
}).strict();

export const ZenoRecommendationSchema = z.object({
  action: z.string().max(600),
  rationale: z.string().max(800),
  page: z.string().max(240).nullable(),
}).strict();
export type ZenoRecommendation = z.infer<typeof ZenoRecommendationSchema>;

export const ZenoInvestigationSchema = z.object({
  tools_used: z.array(z.string()),
  tool_errors: z.array(z.string()),
  provider: z.string().nullable(),
  model: z.string().nullable(),
  latency_ms: z.number().int().nonnegative(),
  synthesis: z.enum(["model", "fallback", "clarify", "no_evidence"]),
}).strict();
export type ZenoInvestigation = z.infer<typeof ZenoInvestigationSchema>;

export const ZenoAnswerSchema = z.object({
  headline: z.string().max(300),
  summary: z.string().max(4000),
}).strict();

export const ZenoChatResponseSchema = z.object({
  conversation_id: z.string().regex(ZENO_CONVERSATION_ID_PATTERN),
  answer: ZenoAnswerSchema,
  findings: z.array(ZenoFindingSchema),
  possible_causes: z.array(ZenoInterpretationSchema),
  recommendations: z.array(ZenoRecommendationSchema),
  evidence: z.array(ZenoEvidenceSchema),
  limitations: z.array(z.string()),
  related_pages: z.array(z.string().max(240)),
  suggested_questions: z.array(z.string()),
  generated_at: UtcDateTimeSchema,
  investigation: ZenoInvestigationSchema,
}).strict();
export type ZenoChatResponse = z.infer<typeof ZenoChatResponseSchema>;

export const ZenoChatContextSchema = z.object({
  page: z.string().max(80).regex(/^\/[A-Za-z0-9/_-]*$/).optional(),
  period_days: z.number().int().min(ZENO_CHAT_PERIOD.min).max(ZENO_CHAT_PERIOD.max).optional(),
}).strict();

/** The request the browser sends. `conversation_id` is omitted to start a new investigation. */
export const ZenoChatRequestSchema = z.object({
  conversation_id: z.string().regex(ZENO_CONVERSATION_ID_PATTERN).optional(),
  message: z.string().trim().min(1).max(2000),
  context: ZenoChatContextSchema.optional(),
}).strict();
export type ZenoChatRequest = z.input<typeof ZenoChatRequestSchema>;

export const ZenoStatusSchema = z.object({
  enabled: z.boolean(),
  model_gateway_ready: z.boolean(),
  providers_configured: z.array(z.string().min(1).max(40)),
  tool_registry_ready: z.boolean(),
  tool_count: z.number().int().nonnegative(),
  last_error_category: z.string().max(80).nullable(),
  generated_at: UtcDateTimeSchema,
}).strict();
export type ZenoStatus = z.infer<typeof ZenoStatusSchema>;

export const ZenoBriefingSeveritySchema = z.enum(["critical", "high", "warning", "positive", "info"]);
export type ZenoBriefingSeverity = z.infer<typeof ZenoBriefingSeveritySchema>;

export const ZenoBriefingFindingSchema = z.object({
  id: z.string().max(120),
  severity: ZenoBriefingSeveritySchema,
  title: z.string().max(300),
  detail: z.string().max(1200),
  area: z.string().max(60),
  evidence: z.array(z.string()).max(12),
  // False marks a signal with no quantitative evidence attached, such as an alert.
  evidence_backed: z.boolean(),
  href: z.string().max(240).nullable(),
}).strict();
export type ZenoBriefingFinding = z.infer<typeof ZenoBriefingFindingSchema>;

export const ZenoBriefingOpportunitySchema = z.object({
  title: z.string().max(300),
  detail: z.string().max(1200),
  href: z.string().max(240).nullable(),
}).strict();
export type ZenoBriefingOpportunity = z.infer<typeof ZenoBriefingOpportunitySchema>;

export const ZenoBriefingSchema = z.object({
  headline: z.string().max(300),
  executive_summary: z.string().max(6000),
  priority_findings: z.array(ZenoBriefingFindingSchema),
  opportunities: z.array(ZenoBriefingOpportunitySchema),
  recommended_investigations: z.array(z.string()),
  evidence: z.array(ZenoEvidenceSchema),
  period: ZenoPeriodSchema,
  generated_at: UtcDateTimeSchema,
  // Backend dict[str, Any]: known keys are read by name, and absent keys stay absent.
  data_freshness: z.record(z.string(), z.unknown()),
  limitations: z.array(z.string()),
  cached: z.boolean(),
}).strict();
export type ZenoBriefing = z.infer<typeof ZenoBriefingSchema>;

export const ZenoConversationSummarySchema = z.object({
  id: z.string().regex(ZENO_CONVERSATION_ID_PATTERN),
  title: z.string().max(200),
  created_at: UtcDateTimeSchema,
  updated_at: UtcDateTimeSchema,
  expires_at: UtcDateTimeSchema,
  turn_count: z.number().int().nonnegative(),
}).strict();
export type ZenoConversationSummary = z.infer<typeof ZenoConversationSummarySchema>;

export const ZenoConversationListSchema = z.object({
  conversations: z.array(ZenoConversationSummarySchema),
  total: z.number().int().nonnegative(),
  limit: z.number().int().min(ZENO_LIST_PAGE.min).max(ZENO_LIST_PAGE.max),
  offset: z.number().int().nonnegative(),
}).strict();
export type ZenoConversationList = z.infer<typeof ZenoConversationListSchema>;

export const ZenoTurnSchema = z.object({
  id: z.string().min(1).max(64),
  role: z.enum(["user", "assistant"]),
  content: z.string(),
  evidence: z.array(ZenoEvidenceSchema),
  metadata: z.record(z.string(), z.unknown()),
  created_at: UtcDateTimeSchema,
}).strict();
export type ZenoTurn = z.infer<typeof ZenoTurnSchema>;

export const ZenoConversationDetailSchema = z.object({
  conversation: ZenoConversationSummarySchema,
  turns: z.array(ZenoTurnSchema),
  limit: z.number().int().min(ZENO_TURN_PAGE.min).max(ZENO_TURN_PAGE.max),
  offset: z.number().int().nonnegative(),
}).strict();
export type ZenoConversationDetail = z.infer<typeof ZenoConversationDetailSchema>;

export const ZenoDeleteResultSchema = z.object({
  deleted: z.literal(true),
  id: z.string().regex(ZENO_CONVERSATION_ID_PATTERN),
}).strict();

/**
 * The metadata the orchestrator stores on a turn. It is a dict on the backend,
 * so each key is optional and unknown keys pass through without being read.
 */
export const ZenoTurnMetadataSchema = z.object({
  investigation: ZenoInvestigationSchema.optional(),
  limitations: z.array(z.string()).optional(),
}).passthrough();
